const int HZFont_Count = sizeof(HZFont) / sizeof(HZFont[0]);

const uint8_t *HZ_Lookup(uint16_t gbk_code) {
    int lo = 0, hi = HZFont_Count - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (HZFont[mid].gbk_code == gbk_code) return HZFont[mid].bits;
        if (HZFont[mid].gbk_code < gbk_code) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}
